.wrap{max-width:720px;margin:0 auto;padding:24px 16px}
h1{font-size:26px;font-weight:800;margin:0 0 4px}h2{font-size:18px;font-weight:800;margin:24px 0 8px}
.soft{color:var(--ink-soft);font-size:13px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:14px}
.pill{display:inline-flex;align-items:center;gap:4px;border-radius:999px;font-weight:800;padding:2px 8px;font-size:11px}
.pill.md{padding:4px 10px;font-size:12px}
.featured{background:var(--ink);color:var(--on-ink)}
.gift{background:var(--primary-soft);color:var(--primary-fg)}.swap{background:var(--accent-soft);color:var(--accent-fg)}
.points{background:var(--orange);color:var(--ink)}.reserved{background:var(--teal-soft);color:var(--ink)}
.pills{display:flex;flex-wrap:wrap;gap:4px}
.thumb{width:48px;height:48px;border-radius:12px;background:var(--cream);flex:none;display:flex;align-items:center;justify-content:center;color:var(--ink-soft);font-size:18px}
.row{display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid var(--line)}
.row:first-child{border-top:0}
.name{font-size:15px}
.person{display:flex;align-items:center;gap:12px;margin-top:16px}
.avatar{width:40px;height:40px;border-radius:50%;background:var(--primary);color:var(--on-primary);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:13px}
.preview{margin-left:52px}
.more{display:inline-block;margin-top:4px;font-weight:800;font-size:14px;color:var(--primary-fg)}
.chev{color:var(--ink-soft);margin-left:auto}
.mark{outline:2px dashed var(--orange);outline-offset:3px;border-radius:10px}
.note{background:var(--cream);border:1px dashed var(--line-strong);border-radius:14px;padding:10px 12px;font-size:13px;margin-top:16px}

