.mb.on{border:0}.mb.on.gift{background:var(--primary);color:var(--on-primary)}.mb.on.swap{background:var(--accent);color:var(--ink)}.mb.on.points{background:var(--orange);color:var(--ink)}
.ctl{display:flex;align-items:center;gap:10px;margin-top:8px;flex-wrap:wrap}
.seg{display:grid;grid-template-columns:1fr 1fr;gap:2px;background:var(--line);border-radius:999px;padding:2px}
.seg button{min-height:36px;border:0;border-radius:999px;background:none;padding:0 12px;font-weight:800;font-size:13px;color:var(--ink-soft)}
.seg button.on{background:var(--paper);color:var(--ink);box-shadow:0 2px 6px -2px rgba(19,38,29,.25)}
.star{min-height:36px;border-radius:999px;border:1.5px solid var(--line-strong);background:var(--paper);padding:0 14px;font-weight:800;font-size:13px;color:var(--ink)}
.star.on{background:var(--ink);color:var(--on-ink);border-color:var(--ink)}
.draft{margin-top:12px;background:var(--primary-soft);color:var(--primary-fg);border-radius:16px;padding:10px 14px;font-size:13px}
.toast{position:sticky;top:8px;z-index:5;background:var(--danger-soft);color:var(--danger);border-radius:14px;padding:10px 14px;font-weight:700;font-size:14px;display:flex;justify-content:space-between}

