.avatar{width:40px;height:40px;border-radius:50%;background:var(--primary);color:var(--on-primary);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:13px}
.preview{margin-left:52px}
.more{display:inline-block;margin-top:4px;font-weight:800;font-size:14px;color:var(--primary-fg)}
.chev{color:var(--ink-soft);margin-left:auto}
.mark{outline:2px dashed var(--orange);outline-offset:3px;border-radius:10px}
.note{background:var(--cream);border:1px dashed var(--line-strong);border-radius:14px;padding:10px 12px;font-size:13px;margin-top:16px}

.shell{display:flex;min-height:100vh}.side{width:220px;background:var(--paper);border-right:1px solid var(--line);padding:16px}
.side a{display:block;padding:8px 10px;border-radius:8px;color:var(--ink);text-decoration:none;font-size:14px}.side a.on{background:var(--primary-soft);color:var(--primary-fg);font-weight:700}
.main{flex:1;padding:24px 32px;max-width:760px}
fieldset{border:1px solid var(--line);border-radius:12px;padding:16px;margin-top:16px;background:var(--paper)}legend{font-weight:700;padding:0 6px}
label{display:block;font-weight:600;font-size:14px;margin-bottom:6px}
input{width:140px;padding:8px 10px;border:1px solid var(--line-strong);border-radius:8px;font-size:15px}
.help{font-size:13px;color:var(--ink-soft);margin-top:6px}
.btn{margin-top:16px;padding:10px 18px;border:0;border-radius:8px;background:var(--primary);color:var(--on-primary);font-weight:700}
.alert{margin-top:12px;padding:10px 14px;border-radius:8px;background:var(--danger-soft);color:var(--danger);font-size:14px}
.err{color:var(--danger);font-size:13px;margin-top:6px}
